insert into category_three.question_bank (id, prompt, theme, answers, sort_order, version)
select r->>'id', r->>'prompt', r->>'theme', array(select jsonb_array_elements_text(r->'answers')), (r->>'sort_order')::int, r->>'version'
from jsonb_array_elements('[{"id":"classic-101","prompt":"Where is power most often felt in everyday life?","theme":"Power, Rules & Institutions","answers":["Schedules","Rules","Prices","Expectations"],"sort_order":101,"version":"classic"},{"id":"classic-102","prompt":"When does a rule feel most legitimate?","theme":"Power, Rules & Institutions","answers":["Its purpose is clear","It is applied fairly","People have a voice","It can be challenged"],"sort_order":102,"version":"classic"},{"id":"classic-103","prompt":"What is a subtle form of social control?","theme":"Power, Rules & Institutions","answers":["Ranking","Tracking","Labeling","Rewarding conformity"],"sort_order":103,"version":"classic"},{"id":"classic-104","prompt":"How does an institution earn trust?","theme":"Power, Rules & Institutions","answers":["Transparency","Accountability","Participation","Consistency"],"sort_order":104,"version":"classic"},{"id":"classic-105","prompt":"Why do people follow rules they do not agree with?","theme":"Power, Rules & Institutions","answers":["Fear of consequences","Need for access","Habit","Social pressure"],"sort_order":105,"version":"classic"},{"id":"classic-106","prompt":"What is usually the first step in resisting unfair power?","theme":"Power, Rules & Institutions","answers":["Naming the problem","Quietly refusing","Finding allies","Imagining an alternative"],"sort_order":106,"version":"classic"},{"id":"classic-107","prompt":"What kind of power is hardest to notice?","theme":"Power, Rules & Institutions","answers":["Normalized routines","Expert language","Market incentives","Social expectations"],"sort_order":107,"version":"classic"},{"id":"classic-108","prompt":"How can inequality be made to look normal?","theme":"Power, Rules & Institutions","answers":["Call it personal failure","Call it natural difference","Call it free choice","Call it efficiency"],"sort_order":108,"version":"classic"},{"id":"classic-109","prompt":"When does an institution make a person feel like a number?","theme":"Power, Rules & Institutions","answers":["Metrics dominate","Context is ignored","Time is too limited","Decisions are automated"],"sort_order":109,"version":"classic"},{"id":"classic-110","prompt":"What is the strongest counterweight to concentrated power?","theme":"Power, Rules & Institutions","answers":["Collective action","Public oversight","Local control","Transparency"],"sort_order":110,"version":"classic"},{"id":"classic-111","prompt":"How does punishment most often change behavior?","theme":"Power, Rules & Institutions","answers":["Through fear","Through exclusion","Through shame","Through lost opportunities"],"sort_order":111,"version":"classic"},{"id":"classic-112","prompt":"What most encourages people to comply without being forced?","theme":"Power, Rules & Institutions","answers":["Rewards","Convenience","Uncertainty","Peer pressure"],"sort_order":112,"version":"classic"},{"id":"classic-113","prompt":"When does a rule become harmful even if it began with a good purpose?","theme":"Power, Rules & Institutions","answers":["Exceptions become impossible","Context gets ignored","Costs fall unevenly","Dissent gets punished"],"sort_order":113,"version":"classic"},{"id":"classic-114","prompt":"What is a sign that people have internalized external control?","theme":"Power, Rules & Institutions","answers":["They constantly self-monitor","They constantly self-blame","They compete constantly","They anticipate judgment"],"sort_order":114,"version":"classic"},{"id":"classic-115","prompt":"What keeps a social hierarchy in place most effectively?","theme":"Power, Rules & Institutions","answers":["Money","Status","Tradition","Access"],"sort_order":115,"version":"classic"},{"id":"classic-116","prompt":"Besides fewer restrictions, what does real freedom require?","theme":"Power, Rules & Institutions","answers":["Resources","Time","Support","Security"],"sort_order":116,"version":"classic"},{"id":"classic-117","prompt":"When does bureaucracy feel most dehumanizing?","theme":"Power, Rules & Institutions","answers":["There is no discretion","There is no explanation","There is no human contact","There is no appeal"],"sort_order":117,"version":"classic"},{"id":"classic-118","prompt":"How does surveillance most often change people''s behavior?","theme":"Power, Rules & Institutions","answers":["More caution","More conformity","More anxiety","More self-censorship"],"sort_order":118,"version":"classic"},{"id":"classic-119","prompt":"What does shared power look like in practice?","theme":"Power, Rules & Institutions","answers":["Co-decision","Rotating leadership","Open information","Mutual accountability"],"sort_order":119,"version":"classic"},{"id":"classic-120","prompt":"When are people most likely to challenge authority?","theme":"Power, Rules & Institutions","answers":["When harm becomes visible","When alternatives exist","When allies gather","When legitimacy weakens"],"sort_order":120,"version":"classic"},{"id":"classic-121","prompt":"What makes a community feel real rather than just nearby?","theme":"Community, Solidarity & Commons","answers":["Shared work","Shared meals","Mutual aid","Shared decisions"],"sort_order":121,"version":"classic"},{"id":"classic-122","prompt":"When does solidarity feel strongest?","theme":"Community, Solidarity & Commons","answers":["People show up","People share risk","People share resources","People listen across differences"],"sort_order":122,"version":"classic"},{"id":"classic-123","prompt":"What is most likely to weaken a shared public resource?","theme":"Community, Solidarity & Commons","answers":["Privatization","Neglect","Competition","Short-term thinking"],"sort_order":123,"version":"classic"},{"id":"classic-124","prompt":"What makes people more willing to cooperate?","theme":"Community, Solidarity & Commons","answers":["Trust","Fair rules","Visible needs","Shared benefits"],"sort_order":124,"version":"classic"},{"id":"classic-125","prompt":"How is a shared resource most likely to be cared for?","theme":"Community, Solidarity & Commons","answers":["Clear responsibility","Local knowledge","Mutual accountability","Regular daily use"],"sort_order":125,"version":"classic"},{"id":"classic-126","prompt":"What weakens community connections fastest?","theme":"Community, Solidarity & Commons","answers":["Everyone being overworked","People moving constantly","Public spaces disappearing","Competition increasing"],"sort_order":126,"version":"classic"},{"id":"classic-127","prompt":"What makes collective action sustainable?","theme":"Community, Solidarity & Commons","answers":["Friendship","Achievable goals","Shared leadership","Celebration"],"sort_order":127,"version":"classic"},{"id":"classic-128","prompt":"What creates a strong sense of belonging?","theme":"Community, Solidarity & Commons","answers":["Repetition","Contribution","Recognition","Shared memory"],"sort_order":128,"version":"classic"},{"id":"classic-129","prompt":"Besides a goal, what do people need from a social movement?","theme":"Community, Solidarity & Commons","answers":["Relationships","Joy","Safety","Learning"],"sort_order":129,"version":"classic"},{"id":"classic-130","prompt":"When can disagreement actually strengthen a group?","theme":"Community, Solidarity & Commons","answers":["It stays respectful","It stays specific","It stays transparent","It stays connected to a shared purpose"],"sort_order":130,"version":"classic"},{"id":"classic-131","prompt":"What makes mutual aid feel different from simple charity?","theme":"Community, Solidarity & Commons","answers":["Reciprocity","Equality","Relationship","Shared struggle"],"sort_order":131,"version":"classic"},{"id":"classic-132","prompt":"What is a good sign that a group is avoiding burnout?","theme":"Community, Solidarity & Commons","answers":["Tasks are shared","Rest is accepted","Wins are noticed","People are supported"],"sort_order":132,"version":"classic"},{"id":"classic-133","prompt":"How does community knowledge grow best?","theme":"Community, Solidarity & Commons","answers":["Storytelling","Practice","Mentoring","Debate"],"sort_order":133,"version":"classic"},{"id":"classic-134","prompt":"What can collective care solve better than individual effort alone?","theme":"Community, Solidarity & Commons","answers":["Isolation","Time pressure","Resource gaps","Lack of access"],"sort_order":134,"version":"classic"},{"id":"classic-135","prompt":"What makes a public space feel truly communal?","theme":"Community, Solidarity & Commons","answers":["People feel welcome","People feel safe","There is shared activity","People help care for it"],"sort_order":135,"version":"classic"},{"id":"classic-136","prompt":"What does it mean to turn something into a commons?","theme":"Community, Solidarity & Commons","answers":["Make it shared","Make it cared for","Govern it collectively","Keep it widely accessible"],"sort_order":136,"version":"classic"},{"id":"classic-137","prompt":"Why do people defend a shared resource most strongly?","theme":"Community, Solidarity & Commons","answers":["They need it daily","It creates belonging","It represents fairness","Future generations need it"],"sort_order":137,"version":"classic"},{"id":"classic-138","prompt":"What makes cooperation break down fastest?","theme":"Community, Solidarity & Commons","answers":["Low trust","Unequal effort","Closed decisions","Uneven rewards"],"sort_order":138,"version":"classic"},{"id":"classic-139","prompt":"What makes a group more resilient?","theme":"Community, Solidarity & Commons","answers":["Skills are distributed","Information is shared","Leadership is shared","Relationships are strong"],"sort_order":139,"version":"classic"},{"id":"classic-140","prompt":"Name an activity that can make collective life feel joyful.","theme":"Community, Solidarity & Commons","answers":["Cooking together","Singing together","Building something together","Celebrating together"],"sort_order":140,"version":"classic"},{"id":"classic-141","prompt":"How does the body remind us that humans are part of nature?","theme":"Nature, Ecology & Interdependence","answers":["Sleep cycles","Sensitivity to weather","Need for fresh air","Need for movement"],"sort_order":141,"version":"classic"},{"id":"classic-142","prompt":"Where does environmental harm feel most personal?","theme":"Nature, Ecology & Interdependence","answers":["Air","Water","Food","Noise"],"sort_order":142,"version":"classic"},{"id":"classic-143","prompt":"What does modern life separate people from most easily?","theme":"Nature, Ecology & Interdependence","answers":["Seasons","Land","Community","Bodily rhythms"],"sort_order":143,"version":"classic"},{"id":"classic-144","prompt":"Why can time in nature feel restorative?","theme":"Nature, Ecology & Interdependence","answers":["More quiet","Different sensory input","More movement","Distance from screens"],"sort_order":144,"version":"classic"},{"id":"classic-145","prompt":"If the body is not a machine, what is a better metaphor?","theme":"Nature, Ecology & Interdependence","answers":["An organism","An ecosystem","A relationship","A living history"],"sort_order":145,"version":"classic"},{"id":"classic-146","prompt":"What is the clearest sign that an environment supports wellbeing?","theme":"Nature, Ecology & Interdependence","answers":["Clean air","Green space","Safe water","Quiet places"],"sort_order":146,"version":"classic"},{"id":"classic-147","prompt":"Which human limit is hardest for technology to erase?","theme":"Nature, Ecology & Interdependence","answers":["Need for sleep","Need for connection","Need for rest","Need for a healthy environment"],"sort_order":147,"version":"classic"},{"id":"classic-148","prompt":"What makes people feel more connected to the place where they live?","theme":"Nature, Ecology & Interdependence","answers":["Walking","Gardening","Local food","Knowing neighbors"],"sort_order":148,"version":"classic"},{"id":"classic-149","prompt":"Where is environmental inequality easiest to notice?","theme":"Nature, Ecology & Interdependence","answers":["Pollution exposure","Extreme heat","Access to green space","Water quality"],"sort_order":149,"version":"classic"},{"id":"classic-150","prompt":"What should the idea of progress protect, not just create?","theme":"Nature, Ecology & Interdependence","answers":["Livable ecosystems","Human time","Biodiversity","Community"],"sort_order":150,"version":"classic"}]'::jsonb) r;